# Check chromatic number using greedy coloring and backtracking
def is_valid_coloring(graph, colors):
    for u in range(len(graph)):
        for v in graph[u]:
            if colors[u] == colors[v]:
                return False
    return True

def chromatic_number(graph, n):
    # Try k colors from 1 to n
    for k in range(1, n + 1):
        colors = [-1] * n
        def backtrack(v):
            if v == n:
                return True
            for c in range(k):
                valid = True
                for u in graph[v]:
                    if colors[u] == c:
                        valid = False
                        break
                if valid:
                    colors[v] = c
                    if backtrack(v + 1):
                        return True
                    colors[v] = -1
            return False
        if backtrack(0):
            return k, colors
    return n, list(range(n))

